args.query:
select schemaname,tablename,policyname,cmd,roles,qual,with_check from pg_policies;
select tgname,tgrelid::regclass,pg_get_triggerdef(oid) from pg_trigger where not tgisinternal;
select n.nspname,p.proname,p.prosecdef,pg_get_functiondef(p.oid) from pg_proc p join pg_namespace n on n.oid=pronamespace where nspname in ('api','public');

select p.proname,pg_get_functiondef(p.oid) from pg_proc p join pg_namespace n on n.oid=pronamespace where nspname='private';
select grantee,table_name,privilege_type,column_name from information_schema.column_privileges where table_schema='api' and grantee not in ('postgres') order by 2,1,3,4;
select grantee,table_name,privilege_type from information_schema.table_privileges where table_schema='api' and grantee not in ('postgres') order by 2,1;
select * from api.status; select * from api.app_user; select relname,relrowsecurity,relforcerowsecurity from pg_class where relnamespace='api'::regnamespace and relkind='r';

alter table api.application add column internal_score numeric;
grant select (internal_score), update (internal_score) on api.application to expert;
grant select (internal_score), update (internal_score), insert (internal_score) on api.application to fund_admin;
select grantee,privilege_type from information_schema.column_privileges where table_schema='api' and table_name='application' and column_name='internal_score';
select id,status_id,company_id from api.application order by id limit 8;
